def normalized(text):
    text = unicodedata.normalize('NFKC', text).casefold().replace('ё','е')
    return re.sub(r'[^\w]+', ' ', text).strip()

def forms(topic):
    if topic == 'техническая оптимизация сайта':
        return {'nom':topic,'acc':'техническую оптимизацию сайта','gen':'технической оптимизации сайта'}
    first, rest = topic.split(' ', 1)
    acc, gen = CASES[first]
    return {'nom': topic, 'acc': acc+' '+rest, 'gen':gen+' '+rest}

def write_csv(path, rows):
    with path.open('w', encoding='utf-8-sig', newline='') as f:
        csv.writer(f).writerows(rows)

def main():
    OUT.mkdir(parents=True, exist_ok=True)
    with (SEO/'wordstat-commercial.csv').open(encoding='utf-8-sig',newline='') as f:
        verified = list(csv.DictReader(f))
    header = ['Страница','Фраза','Кластер / тема','Намерение','Статус проверки','Широкая частотность Wordstat','Период','Регион','Источник','Следующий шаг']
    all_rows, summary = [], []
    for slug, topic_string in TOPICS.items():
        page = '/services/'+slug
        topics = topic_string.split('|')
        assert len(topics)==25 and len(PATTERNS)==40
        rows, seen = [], set()
        def add(row):
            key = normalized(row[1])
            if key in seen or len(rows)>=1000: return
            seen.add(key); rows.append(row)
        measured = sorted([r for r in verified if r['Страница']==page],key=lambda r:-int(r['Широкая частотность']))
        for row in measured:
            add([page,row['Фраза из Wordstat'],'Наблюдавшийся запрос','Коммерческий','Наблюдался в Wordstat',row['Широкая частотность'],row['Период'],'Россия',row['Источник'],'Проверить точную частотность и выдачу за единый период'])
        # Round-robin maintains coverage of all topics before adding more variants.
        for pattern, intent in PATTERNS:
            for topic in topics:
                phrase = pattern.format(**forms(topic))
                add([page,phrase,topic,intent,'Сгенерированный кандидат — спрос не проверен','','','Россия','Идея на основе темы услуги; не выгрузка Wordstat','Проверить спрос, выдачу, соответствие услуге и пересечения'])
        # A measured query can duplicate a generated one. Extend only with an
        # explicit alternative commercial formulation to keep exactly 1000.
        for topic in topics:
            add([page,'обсудить '+forms(topic)['acc'],topic,'Коммерческий','Сгенерированный кандидат — спрос не проверен','','','Россия','Идея на основе темы услуги; не выгрузка Wordstat','Проверить спрос и естественность формулировки'])
        assert len(rows)==1000 and len(seen)==1000, (slug,len(rows))
        write_csv(OUT/(slug+'.csv'),[header,*rows])
        all_rows.extend(rows)
        count = sum(r[4]=='Наблюдался в Wordstat' for r in rows)
        summary.append([page,len(rows),count,len(rows)-count,len(topics)])
    owners = {}
    for row in all_rows: owners.setdefault(normalized(row[1]),set()).add(row[0])
    overlaps = [[phrase,' | '.join(sorted(pages)),'Выбрать одну основную страницу после проверки выдачи'] for phrase,pages in owners.items() if len(pages)>1]
    write_csv(OUT/'all-services-17000.csv',[header,*all_rows])
    write_csv(OUT/'summary.csv',[['Страница','Всего фраз','С частотностью Wordstat','Непроверенные кандидаты','Тем'],*summary])
    write_csv(OUT/'overlaps.csv',[['Нормализованная фраза','Страницы','Рекомендация'],*overlaps])
    assert len(all_rows)==17000
    archive = SEO/'DAMVI-semantics-17000.zip'
    with ZipFile(archive,'w',ZIP_DEFLATED) as z:
        for p in sorted(OUT.glob('*')):
            if p.is_file(): z.write(p,'keywords-1000/'+p.name)
        for name in ['План-SEO-DAMVI.txt','wordstat-commercial.csv','wordstat-seeds.csv','pages.csv','Работа-с-расширенной-семантикой.txt','keyword-coverage-17000.csv','keyword-coverage-summary.csv','Проверка-размещения-ключей.txt']:
            p=SEO/name
            if p.exists():z.write(p,p.name)
    print(f'{len(TOPICS)} services × 1000 = {len(all_rows)} rows; {len(verified)} measured rows; {len(overlaps)} exact cross-page overlaps. Archive: {archive}')

if __name__=='__main__':main()
